sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    //Type appropriate comment here, and begin script below

    // Create GlideDate object
    if (!newValue) {
        g_form.clearValue('day_of_week');
        g_form.clearValue('u_order');
        return;
    }

    // Convert ServiceNow date string (yyyy-MM-dd) into JS Date
    var parts = newValue.split("-");
    var jsDate = new Date(parts[0], parts[1] - 1, parts[2]);

    // JS: 0 = Sunday, 1 = Monday, etc.
    var dayNumber = jsDate.getDay();

    var dayMap = {
        1: {
            value: 'monday',
            order: '100'
        },
        2: {
            value: 'tuesday',
            order: '200'
        },
        3: {
            value: 'wednesday',
            order: '300'
        },
        4: {
            value: 'thursday',
            order: '400'
        },
        5: {
            value: 'friday',
            order: '500'
        },
        6: {
            value: 'saturday',
            order: '600'
        }
    };

    var result = dayMap[dayNumber];

    if (result) {
        g_form.setValue('day_of_week', result.value);
        g_form.setValue('u_order', result.order);
    }

}
